from collections import Counter
from typing import List

def digits(n: int, base: int = 10) -> List[int]:
    if base < 2 or n < 0: raise ValueError("invalid input")
    if n == 0: return [0]
    out: List[int] = []
    while n:
        n, r = divmod(n, base); out.append(r)
    return out

def is_fang_pair(x: int, y: int, base: int = 10) -> bool:
    return Counter(digits(x*y, base)) == Counter(digits(x, base) + digits(y, base))

for x, y in [(21,60),(15,93),(35,41),(30,51),(21,87),(27,81),(80,86)]:
    print(f"{x*y} = {x} * {y}: {is_fang_pair(x,y)}")

from math import gcd
from typing import List, Tuple

def curve_points(base: int) -> List[Tuple[int, int]]:
    if base < 2: raise ValueError("base must be at least 2")
    m = base - 1
    return [(x,y) for x in range(m) for y in range(m)
            if m == 1 or ((x-1)*(y-1)) % m == 1]

for b in range(3, 17):
    points = curve_points(b)
    units = sum(gcd(u,b-1) == 1 for u in range(b-1))
    print(f"base {b:2}: {len(points):2} points, phi(base-1)={units:2}")

from typing import List, Tuple

def decimal_curve() -> List[Tuple[int, int]]:
    return [(x,y) for x in range(9) for y in range(9)
            if ((x-1)*(y-1)) % 9 == 1]

prime_compatible = [(x,y) for x,y in decimal_curve()
                    if x not in (0,3,6) and y not in (0,3,6)]
for point in prime_compatible:
    print(point, "product residue", point[0]*point[1] % 9)

